package org.joda.time.field;

import java.io.*;
import java.math.*;
import java.util.*;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeFieldType;
import org.joda.time.IllegalFieldValueException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FieldUtils_safeMultiply_TriageGen0Test {

    @Test
    public void testSafeMultiply_CaseMinusOne() {
        assertEquals(-10L, FieldUtils.safeMultiply(10L, -1));
        assertEquals(10L, FieldUtils.safeMultiply(-10L, -1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, -1));
    }

    @Test
    public void testSafeMultiply_CaseZero() {
        assertEquals(0L, FieldUtils.safeMultiply(10L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(-10L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 0));
    }

    @Test
    public void testSafeMultiply_CaseOne() {
        assertEquals(10L, FieldUtils.safeMultiply(10L, 1));
        assertEquals(-10L, FieldUtils.safeMultiply(-10L, 1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 1));
    }

    @Test
    public void testSafeMultiply_NormalMultiplication() {
        assertEquals(20L, FieldUtils.safeMultiply(10L, 2));
        assertEquals(-20L, FieldUtils.safeMultiply(10L, -2));
        assertEquals(20L, FieldUtils.safeMultiply(-10L, -2));
        assertEquals(0L, FieldUtils.safeMultiply(10L, -0)); // redundant due to case 0 but covers logic
    }

    @Test
    public void testSafeMultiply_Overflow() {
        // Long.MAX_VALUE is 9223372036854775807L
        // Test overflow with a positive val1 and positive val2
        try {
            FieldUtils.safeMultiply(Long.MAX_VALUE, 2);
            org.junit.Assert.fail("Expected ArithmeticException for overflow");
        } catch (ArithmeticException e) {
            assertEquals("Multiplication overflows a long: 9223372036854775807 * 2", e.getMessage());
        }

        // Test overflow with a negative val1 and positive val2
        try {
            FieldUtils.safeMultiply(Long.MIN_VALUE, 2);
            org.junit.Assert.fail("Expected ArithmeticException for overflow");
        } catch (ArithmeticException e) {
            assertEquals("Multiplication overflows a long: -9223372036854775808 * 2", e.getMessage());
        }

        // Test overflow with a positive val1 and negative val2
        try {
            FieldUtils.safeMultiply(Long.MAX_VALUE, -2);
            org.junit.Assert.fail("Expected ArithmeticException for overflow");
        } catch (ArithmeticException e) {
            assertEquals("Multiplication overflows a long: 9223372036854775807 * -2", e.getMessage());
        }
    }

    @Test
    public void testSafeMultiply_BoundaryValues() {
        // Test with Integer.MAX_VALUE and Integer.MIN_VALUE as val2
        assertEquals(Long.MAX_VALUE, FieldUtils.safeMultiply(1L, Integer.MAX_VALUE));
        // Note: Long.MIN_VALUE / -1 is still Long.MIN_VALUE in 2's complement, 
        // but the method has a specific case for -1.
        assertEquals(Long.MIN_VALUE, FieldUtils.safeMultiply(1L, Integer.MIN_VALUE));
    }
}
